void ScriptSession::startLocustSwarm(std::uint32_t caster,const SpellInfo& spell,unsigned owner){
    if(!alive(caster,NativeKind::Unit))return;auto u=units_.at(caster);auto revision=u->castRevision;auto key=std::pair{caster,spell.ability};if(auto previous=locustSwarms_.find(key);previous!=locustSwarms_.end())clearLocustSwarm(previous->second);if(!alive(caster,NativeKind::Unit) || u->removing || number(u->life)<=0 || u->owner!=owner || u->castRevision!=revision)return;if(locustSwarms_.size()>=256 || locustTicket_==UINT64_MAX)throw std::runtime_error("Locust Swarm instance budget exceeded");auto swarm=std::make_shared<LocustSwarm>();swarm->spell=spell;swarm->caster=caster;swarm->owner=owner;swarm->ticket=++locustTicket_;swarm->deathRevision=u->deathRevision;swarm->ownerRevision=u->ownerRevision;swarm->remaining=spell.duration;swarm->visuals=spellVisual(spell,"CasterArt",caster,{u->x,u->y},false);locustSwarms_[key]=std::move(swarm);
}
void ScriptSession::clearLocustSwarm(const std::shared_ptr<LocustSwarm>& value){
    auto swarm=value;auto found=locustSwarms_.find({swarm->caster,swarm->spell.ability});if(found!=locustSwarms_.end() && found->second==swarm)locustSwarms_.erase(found);std::set<std::uint32_t> members;members.swap(swarm->members);for(auto id:swarm->visuals)destroyEffect(id);swarm->visuals.clear();for(auto id:members){auto agent=locustAgents_.find(id);if(agent==locustAgents_.end() || agent->second.swarm!=swarm)continue;locustAgents_.erase(agent);if(alive(id,NativeKind::Unit))removeUnit(id);}
}
void ScriptSession::removeLocust(std::uint32_t id){
    if(auto found=locustAgents_.find(id);found!=locustAgents_.end()){found->second.swarm->members.erase(id);locustAgents_.erase(found);}std::vector<std::shared_ptr<LocustSwarm>> owned;for(auto it=locustSwarms_.lower_bound({id,0});it!=locustSwarms_.end() && it->first.first==id;++it)owned.push_back(it->second);for(auto& swarm:owned)clearLocustSwarm(swarm);
}
bool ScriptSession::locustTarget(const LocustSwarm& swarm,const UnitState& target){
    if(!alive(swarm.caster,NativeKind::Unit) || target.removing || target.hidden() || target.swarmAgent || target.impaledAir() || target.cycloned() || target.sleepProtected() || number(target.life)<=0 || target.invulnerable || capability(target,"Avul") || capability(target,"Aloc") || !enemy(swarm.owner,target.owner) || !unitVisibleTo(target.handle,swarm.owner))return false;auto caster=units_.at(swarm.caster);if(std::hypot(number(target.x)-number(caster->x),number(target.y)-number(caster->y))>swarm.spell.area+target.collision)return false;auto& mask=swarm.spell.allowed;auto classes=target.classifications(definitions().unitClasses(target.type));if(target.building?!mask.contains("structure"):target.airborne()?!mask.contains("air"):!mask.contains("ground"))return false;if(mask.contains("organic") && (target.building || classes.find("mechanical")!=std::string::npos))return false;if(mask.contains("nonancient") && classes.find("ancient")!=std::string::npos)return false;if(classes.find("ward")!=std::string::npos && !mask.contains("ward"))return false;if((mask.contains("hero") || mask.contains("nonhero")) && !(target.hero?mask.contains("hero"):mask.contains("nonhero")))return false;return true;
}
bool ScriptSession::flyLocust(UnitState& unit,WorldPoint point,float height,float stop,double delta){
    float dx=number(point.x)-number(unit.x),dy=number(point.y)-number(unit.y),distance=std::hypot(dx,dy),step=float(delta)*std::max(0.f,number(unit.currentMoveSpeed())*unit.spellMoveFactor());if(distance>stop && distance>.001f){float travel=std::min(step,std::max(0.f,distance-stop));unit.x=real(number(unit.x)+dx/distance*travel);unit.y=real(number(unit.y)+dy/distance*travel);unit.facing=real(std::fmod(std::atan2(dy,dx)*180.f/3.14159265359f+360.f,360.f));if(unit.animation!="Walk"){unit.animation="Walk";unit.animationTime=0;++unit.animationGeneration;}}unit.flyHeight+=std::clamp(height-unit.flyHeight,-step,step);unit.targetFlyHeight=unit.flyHeight;return distance<=stop+step;
}
void ScriptSession::locustDamage(std::uint32_t id,float damage){
    if(damage<=0)return;auto found=locustAgents_.find(id);if(found==locustAgents_.end() || !alive(id,NativeKind::Unit) || units_.at(id)->removing || number(units_.at(id)->life)<=0 || units_.at(id)->deathRevision!=found->second.deathRevision)return;auto swarm=found->second.swarm;auto active=locustSwarms_.find({swarm->caster,swarm->spell.ability});if(active==locustSwarms_.end() || active->second!=swarm || !alive(swarm->caster,NativeKind::Unit))return;auto caster=units_.at(swarm->caster);if(caster->removing || caster->deathRevision!=swarm->deathRevision || caster->ownerRevision!=swarm->ownerRevision || number(caster->life)<=0)return;auto& agent=found->second;agent.carried=std::min(swarm->spell.maxDamage,agent.carried+damage);if(agent.carried>=swarm->spell.maxDamage)agent.returning=true;
}
